(function(){window.bluebirdSwipe=function(area,step){let start=null;let swiped=0;area.style.touchAction="pan-y";area.addEventListener("dragstart",(event)=>event.preventDefault());area.addEventListener("click",(event)=>{if(Date.now()-swiped<400){event.preventDefault();event.stopPropagation();}},true,);area.addEventListener("pointerdown",(event)=>{if(event.isPrimary&&event.button===0){start={x:event.clientX,y:event.clientY};}});area.addEventListener("pointercancel",()=>(start=null));area.addEventListener("pointerup",(event)=>{if(!start||!event.isPrimary){return;}
const dx=event.clientX-start.x;const dy=event.clientY-start.y;start=null;if(Math.abs(dx)<40||Math.abs(dx)<Math.abs(dy)*1.2){return;}
if(String(window.getSelection())){return;}
swiped=Date.now();step(dx<0?1:-1);});};window.bluebirdSwipe.hold=function(area,schedule,hover=false){let focused=false;let resting=false;area.addEventListener("focusin",(event)=>{if(event.target.matches(":focus-visible")){focused=true;schedule();}});area.addEventListener("focusout",(event)=>{if(!area.contains(event.relatedTarget)){focused=false;schedule();}});if(hover){area.addEventListener("pointerenter",(event)=>{if(event.pointerType==="mouse"){resting=true;schedule();}});area.addEventListener("pointerleave",(event)=>{if(event.pointerType==="mouse"){resting=false;schedule();}});}
return()=>focused||resting;};window.bluebirdSwipe.keys=function(dotsBar,step){dotsBar.addEventListener("keydown",(event)=>{const move={ArrowRight:1,ArrowLeft:-1}[event.key];if(move){event.preventDefault();step(move,true);}});};})();